const utils = module.exports;

const TOKEN_KEY_PREFIX = 'token:';
const TOKEN_CREATE_TIME_SET = 'tokens:createtime';
const TOKEN_UID_SET = 'tokens:uid';
const TOKEN_LAST_SEEN_SET = 'tokens:lastSeen';

function validateToken(token) {
