		throw new Error('[[error:invalid-data]]');
	}
}

function toFiniteNumber(value, fallback) {
	const number = Number(value);
	return Number.isFinite(number) ? number : fallback;
}

const tokens = utils.tokens = {};

tokens.list = async function () {
	const tokenIds = await db.getSortedSetRange(TOKEN_CREATE_TIME_SET, 0, -1);
	if (!tokenIds.length) {
		return [];
	}
	const tokenData = await tokens.get(tokenIds);
	return tokenData.filter(Boolean);
};

tokens.get = async function (tokenOrTokens) {
	if (tokenOrTokens === null || tokenOrTokens === undefined) {
		throw new Error('[[error:invalid-data]]');
	}

	const isArray = Array.isArray(tokenOrTokens);
	const tokenIds = isArray ? tokenOrTokens : [tokenOrTokens];
	if (tokenIds.some(token => typeof token !== 'string' || !token.length)) {
		throw new Error('[[error:invalid-data]]');
	}
	if (!tokenIds.length) {
		return [];
	}

	const [storedTokens, lastSeen] = await Promise.all([
		db.getObjects(tokenIds.map(token => `${TOKEN_KEY_PREFIX}${token}`)),
		tokens.getLastSeen(tokenIds),
	]);
	const hydratedTokens = storedTokens.map((tokenData, index) => {
		if (!tokenData) {
			return null;
		}

		return {
			uid: toFiniteNumber(tokenData.uid, 0),
			description: tokenData.description || '',
			timestamp: toFiniteNumber(tokenData.timestamp, 0),
			lastSeen: lastSeen[index],
		};
	});

	return isArray ? hydratedTokens : hydratedTokens[0];
};

tokens.generate = async function (data) {
	if (!data || typeof data !== 'object' || Array.isArray(data)) {
		throw new Error('[[error:invalid-data]]');
	}

	const uid = Number(data.uid);
	if (data.uid === null || data.uid === undefined || data.uid === '' || !Number.isInteger(uid) || uid < 0) {
		throw new Error('[[error:invalid-data]]');
	}
	if (data.description !== undefined && data.description !== null && typeof data.description !== 'string') {
		throw new Error('[[error:invalid-data]]');
	}

	if (uid !== 0) {
		const user = require('../user');
		if (!await user.exists(uid)) {
			throw new Error('[[error:no-user]]');
		}
	}

	const utilsCore = require('../utils');
	const token = utilsCore.generateUUID();
	const timestamp = Date.now();
	if (!Number.isFinite(timestamp)) {
		throw new Error('[[error:invalid-data]]');
	}

	await Promise.all([
		db.setObject(`${TOKEN_KEY_PREFIX}${token}`, {
			uid: uid,
			description: data.description || '',
			timestamp: timestamp,
		}),
		db.sortedSetAdd(TOKEN_CREATE_TIME_SET, timestamp, token),
		db.sortedSetAdd(TOKEN_UID_SET, uid, token),
	]);

	return token;
};

tokens.update = async function (token, data) {
	validateToken(token);
	if (!data || typeof data !== 'object' || Array.isArray(data) || typeof data.description !== 'string') {
		throw new Error('[[error:invalid-data]]');
	}

	const existing = await db.getObject(`${TOKEN_KEY_PREFIX}${token}`);
	if (!existing) {
		throw new Error('[[error:invalid-data]]');
	}

	await db.setObjectField(`${TOKEN_KEY_PREFIX}${token}`, 'description', data.description);
	return await tokens.get(token);
};

tokens.delete = async function (token) {
	validateToken(token);
	await Promise.all([
		db.delete(`${TOKEN_KEY_PREFIX}${token}`),
		db.sortedSetRemove(TOKEN_CREATE_TIME_SET, token),
		db.sortedSetRemove(TOKEN_UID_SET, token),
		db.sortedSetRemove(TOKEN_LAST_SEEN_SET, token),
	]);
};

tokens.log = async function (token) {
	validateToken(token);
	const timestamp = Date.now();
	if (!Number.isFinite(timestamp)) {
		throw new Error('[[error:invalid-data]]');
	}
	await db.sortedSetAdd(TOKEN_LAST_SEEN_SET, timestamp, token);
};

tokens.getLastSeen = async function (tokenIds) {
	if (!Array.isArray(tokenIds) || tokenIds.some(token => typeof token !== 'string' || !token.length)) {
		throw new Error('[[error:invalid-data]]');
	}
	if (!tokenIds.length) {
		return [];
	}

	const scores = await db.sortedSetScores(TOKEN_LAST_SEEN_SET, tokenIds);
	return scores.map(score => (score === null ? null : toFiniteNumber(score, null)));
};

